import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"阿里云百炼学习地图","description":"百炼是模型与应用平台，不是聊天 App，也不是 IDE。先分清「调 API / 订套餐 / 搭应用」，再进教程。","frontmatter":{"title":"阿里云百炼学习地图","description":"百炼是模型与应用平台，不是聊天 App，也不是 IDE。先分清「调 API / 订套餐 / 搭应用」，再进教程。","domain":"product","tags":["model-platform"],"role":"map"},"headers":[],"relativePath":"zh/products/bailian/index.md","filePath":"zh/products/bailian/index.md","lastUpdated":1787110548000}'),l={name:"zh/products/bailian/index.md"};function o(r,a,i,d,p,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="阿里云百炼学习地图" tabindex="-1">阿里云百炼学习地图 <a class="header-anchor" href="#阿里云百炼学习地图" aria-label="Permalink to &quot;阿里云百炼学习地图&quot;">​</a></h1><blockquote><p><strong>阿里云百炼</strong>（Alibaba Cloud Model Studio）是一站式大模型开发与应用平台：开发者走兼容 OpenAI 的 API，业务人员在控制台搭智能体和知识库问答。<a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">产品简介</a></p><p>本页只回答「我要做什么 → 用百炼的哪一块」。操作进 <a href="./bailian.html">教程</a>，查表进 <a href="./bailian-cheatsheet.html">速查</a>，撞名进 <a href="./bailian-glossary.html">术语表</a>。</p><p>模型内部机制不在这里写，见 <a href="/zh/tech/fundamentals/LLM.html">LLM 基础</a> 与 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。</p></blockquote><h2 id="产品全景图" tabindex="-1">产品全景图 <a class="header-anchor" href="#产品全景图" aria-label="Permalink to &quot;产品全景图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阿里云 AI（本站这一目录只写百炼）</span></span>
<span class="line"><span>├── 大模型服务平台百炼（本目录）</span></span>
<span class="line"><span>│   ├── 控制台 / 模型体验</span></span>
<span class="line"><span>│   ├── 模型 API（OpenAI 兼容 / Anthropic 兼容 / DashScope）</span></span>
<span class="line"><span>│   ├── Token Plan / Coding Plan</span></span>
<span class="line"><span>│   ├── 智能体 / 工作流 / 知识库 / MCP</span></span>
<span class="line"><span>│   ├── 百炼 CLI（命令 bl / bailian）</span></span>
<span class="line"><span>│   └── 调优 / 部署 / 评测（地图一行，不写操作）</span></span>
<span class="line"><span>├── 通义千问 — 对话产品，另 issue #83，本目录不写教程</span></span>
<span class="line"><span>├── 通义灵码 / Qoder CN（原 Lingma） — IDE，另 issue #84，本目录不写教程</span></span>
<span class="line"><span>└── 非本站：ECS / OSS / PAI / DashVector / 析言 GBI / 全妙</span></span></code></pre></div><table tabindex="0"><thead><tr><th>官方一级入口</th><th>本站去向</th></tr></thead><tbody><tr><td>产品简介、首次 API、模型体验</td><td><a href="./bailian.html">教程</a></td></tr><tr><td>选择模型、计费、Token Plan、Coding Plan、地域</td><td><a href="./bailian-cheatsheet.html">速查表</a></td></tr><tr><td>接入客户端/开发工具、免费额度用完即停、百炼 CLI、控制台问答</td><td><a href="./bailian-cookbook.html">Cookbook</a></td></tr><tr><td>智能体 1.0 / 2.0、Workspace、三种协议、两套套餐</td><td><a href="./bailian-glossary.html">术语表</a></td></tr><tr><td>调优 / 部署 / 评测</td><td>官方页；本站不拆教程</td></tr><tr><td>通义千问</td><td>地图一行，正文见 #83</td></tr><tr><td>通义灵码 / Qoder CN（原 Lingma）</td><td>地图一行，正文见 #84</td></tr><tr><td>ECS / OSS / PAI / 析言 GBI / 全妙</td><td><strong>非本站</strong></td></tr></tbody></table><h3 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个？ <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个？&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做什么？</span></span>
<span class="line"><span>├── 在自己的前端 / Node 服务里调 Qwen 或第三方模型</span></span>
<span class="line"><span>│   └── → 百炼 API（OpenAI 兼容最省事）→ [教程](./bailian)</span></span>
<span class="line"><span>├── 在 Claude Code / Cursor / Chatbox 里用阿里云的模型额度</span></span>
<span class="line"><span>│   └── → Token Plan（官方推荐新订）或 Coding Plan</span></span>
<span class="line"><span>│       └── Key 和 Base URL 必须成对，见 [Cookbook](./bailian-cookbook)</span></span>
<span class="line"><span>├── 不想写代码，先做一个知识库问答 / 智能体</span></span>
<span class="line"><span>│   └── → 控制台应用（优先 Agent 2.0）</span></span>
<span class="line"><span>├── 让本机 Agent 调图像 / 视频 / 语音等原子能力</span></span>
<span class="line"><span>│   └── → 百炼 CLI（\`bl\`）</span></span>
<span class="line"><span>├── 只是和通义聊天，不接 API、不搭应用</span></span>
<span class="line"><span>│   └── → 通义千问（#83），不是百炼</span></span>
<span class="line"><span>├── 要一个阿里云出品的编码 IDE</span></span>
<span class="line"><span>│   └── → Qoder CN / 通义灵码（#84），不是百炼</span></span>
<span class="line"><span>└── 买云主机 / 对象存储</span></span>
<span class="line"><span>    └── → 非本站。本目录不写 ECS / OSS</span></span></code></pre></div><p>三个最容易付的税：</p><table tabindex="0"><thead><tr><th>容易混的</th><th>区别</th></tr></thead><tbody><tr><td><strong>百炼</strong> vs <strong>千问</strong></td><td>百炼是平台（API + 控制台 + 套餐）。千问是模型，也是独立对话产品。<a href="https://help.aliyun.com/zh/model-studio/faq-about-alibaba-cloud-model-studio" target="_blank" rel="noreferrer">FAQ</a></td></tr><tr><td><strong>百炼</strong> vs <strong>灵码 / Qoder CN</strong></td><td>灵码已改名为 Qoder CN，是 IDE；可以<em>接入</em>百炼的 Key，本身不是百炼。<a href="https://help.aliyun.com/zh/model-studio/lingma-agent" target="_blank" rel="noreferrer">官方接入页</a></td></tr><tr><td><strong>按量 Key</strong> vs <strong>套餐 Key</strong></td><td>按量是 <code>sk-</code> / <code>sk-ws</code>；Coding Plan / Token Plan 专属是 <code>sk-sp-</code>。配错主机要么报 <code>invalid_api_key</code>，要么<strong>悄悄按量扣费</strong>。<a href="https://help.aliyun.com/zh/model-studio/coding-plan" target="_blank" rel="noreferrer">Coding Plan</a></td></tr></tbody></table><h2 id="该读哪一篇" tabindex="-1">该读哪一篇 <a class="header-anchor" href="#该读哪一篇" aria-label="Permalink to &quot;该读哪一篇&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>类型</th><th>什么时候看</th></tr></thead><tbody><tr><td><a href="./bailian.html">上手教程</a></td><td>Tutorial</td><td>第一次：开通 → Key → 第一次 Node 调用</td></tr><tr><td><a href="./bailian-cookbook.html">实战 Cookbook</a></td><td>How-to</td><td>已经会调用，要解决混用、扣费、CLI、无代码应用</td></tr><tr><td><a href="./bailian-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>查地域、URL、套餐对照、官方链接</td></tr><tr><td><a href="./bailian-glossary.html">术语表</a></td><td>Explanation</td><td>名词撞了，或两份官方页口径不一致</td></tr></tbody></table><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><ol><li><strong>先读本页决策树</strong>，确认你要的是平台而不是千问/灵码。</li><li><strong>跟 <a href="./bailian.html">教程</a> 走一遍</strong>：主账号开通、建 Key、环境变量、发一条 <code>qwen-plus</code>。</li><li>要把模型接进产品，翻 <a href="./bailian-cookbook.html">Cookbook · OpenAI 兼容</a>。要把额度接到编程工具，翻 <a href="./bailian-cookbook.html">Cookbook · 不要混用 Key</a>。</li><li>查参数只认 <a href="./bailian-cheatsheet.html">速查表</a> 和官方模型清单。模型名过期极快，<strong>不要在笔记里写死全表</strong>。</li></ol><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">产品页</a></li><li><a href="https://help.aliyun.com/zh/model-studio/what-is-model-studio" target="_blank" rel="noreferrer">什么是阿里云百炼</a></li><li><a href="https://help.aliyun.com/zh/model-studio/models" target="_blank" rel="noreferrer">选择模型</a></li><li><a href="https://www.alibabacloud.com/help/en/model-studio/" target="_blank" rel="noreferrer">国际站 Model Studio</a></li><li><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">控制台</a></li></ul>`,15)])])}const f=t(l,[["render",o]]);export{g as __pageData,f as default};
